import { type FormEvent, useState } from 'react';
import { type StudioUser, type UserRole, useCreateUser, useDeleteUser, useMe, useResetPassword, useUpdateUser, useUsers } from '../api/auth';
import { Badge } from '../components/Badge';
import { Button } from '../components/Button';
import { CommandBox } from '../components/CopyButton';
import { ErrorText, Field, Select, TextInput } from '../components/form';
import { timeAgo } from '../lib/time';

const roleLabels: Record<UserRole, string> = { ADMIN: 'Administrador', MEMBER: 'Membro' };

/** A password generated by the server, shown only once. */
function NewPassword({ who, password, onDone }: { who: string; password: string; onDone: () => void }) {
  return (
    <div className="space-y-2 rounded-lg border border-emerald-500/30 bg-emerald-500/5 p-4">
      <p className="text-sm">
        Senha de <span className="font-medium">{who}</span>. Ela aparece só agora: copie e entregue à pessoa, que pode trocá-la depois no menu do usuário.
      </p>
      <CommandBox command={password} />
      <Button size="sm" onClick={onDone}>
        Já copiei
      </Button>
    </div>
  );
}

/** Users of the Studio (administrators only). Each user sees only their own workspaces and accounts. */
export function UsersPage() {
  const me = useMe();
  const isAdmin = me.data?.role === 'ADMIN';
  const users = useUsers(isAdmin);
  const [shown, setShown] = useState<{ who: string; password: string } | null>(null);

  if (!isAdmin) return <p className="text-sm text-muted">Só administradores gerenciam usuários.</p>;

  return (
    <div className="max-w-5xl space-y-6">
      <div>
        <h1 className="text-xl font-semibold">Usuários</h1>
        <p className="mt-1 text-sm text-muted">
          Cada usuário tem os próprios workspaces, conectores, agentes, workflows e modelo de quadro. A pasta central é a mesma para todos.
        </p>
      </div>

      {shown && <NewPassword who={shown.who} password={shown.password} onDone={() => setShown(null)} />}
      <NewUserForm onCreated={(who, password) => setShown({ who, password })} />

      <ErrorText error={users.error} />
      <div className="overflow-x-auto rounded-lg border border-border">
        <table className="w-full text-left text-sm">
          <thead className="bg-panel text-xs text-muted">
            <tr>
              <th className="px-3 py-2 font-medium">Usuário</th>
              <th className="px-3 py-2 font-medium">Papel</th>
              <th className="px-3 py-2 font-medium">Workspaces</th>
              <th className="px-3 py-2 font-medium">Último acesso</th>
              <th className="px-3 py-2" />
            </tr>
          </thead>
          <tbody>
            {users.data?.map((user) => (
              <UserRow key={user.id} user={user} isSelf={user.id === me.data?.id} onPassword={(password) => setShown({ who: user.name, password })} />
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function UserRow({ user, isSelf, onPassword }: { user: StudioUser; isSelf: boolean; onPassword: (password: string) => void }) {
  const update = useUpdateUser();
  const reset = useResetPassword();
  const remove = useDeleteUser();
  const error = update.error ?? reset.error ?? remove.error;

  return (
    <tr className={`border-t border-border ${user.isActive ? '' : 'opacity-60'}`}>
      <td className="px-3 py-2">
        <div className="flex items-center gap-2">
          <span className="font-medium">{user.name}</span>
          {isSelf && <Badge tone="info">você</Badge>}
          {!user.isActive && <Badge>desativado</Badge>}
        </div>
        <div className="text-xs text-muted">{user.email}</div>
        {error && <div className="mt-1 text-xs text-red-300">{error.message}</div>}
      </td>
      <td className="px-3 py-2">
        <Select
          value={user.role}
          onChange={(event) => update.mutate({ id: user.id, role: event.target.value as UserRole })}
          disabled={isSelf || update.isPending}
          className="w-auto"
        >
          {(Object.keys(roleLabels) as UserRole[]).map((role) => (
            <option key={role} value={role}>
              {roleLabels[role]}
            </option>
          ))}
        </Select>
      </td>
      <td className="px-3 py-2 tabular-nums">{user.workspaceCount}</td>
      <td className="px-3 py-2 whitespace-nowrap text-muted">{user.lastLoginAt ? timeAgo(user.lastLoginAt) : 'nunca'}</td>
      <td className="px-3 py-2">
        {!isSelf && (
          <div className="flex justify-end gap-2">
            <Button
              size="sm"
              onClick={() => window.confirm(`Gerar uma nova senha para ${user.name}? A atual deixa de funcionar.`) && reset.mutate(user.id, { onSuccess: (result) => onPassword(result.password) })}
              disabled={reset.isPending}
            >
              Nova senha
            </Button>
            <Button size="sm" onClick={() => update.mutate({ id: user.id, isActive: !user.isActive })} disabled={update.isPending}>
              {user.isActive ? 'Desativar' : 'Reativar'}
            </Button>
            {user.workspaceCount === 0 && (
              <Button
                size="sm"
                variant="danger"
                onClick={() => window.confirm(`Excluir ${user.name}?`) && remove.mutate(user.id)}
                disabled={remove.isPending}
                title="Só para usuários sem workspaces nem contas"
              >
                Excluir
              </Button>
            )}
          </div>
        )}
      </td>
    </tr>
  );
}

function NewUserForm({ onCreated }: { onCreated: (who: string, password: string) => void }) {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<UserRole>('MEMBER');
  const create = useCreateUser();

  const handleSubmit = (event: FormEvent) => {
    event.preventDefault();
    create.mutate(
      { name: name.trim(), email: email.trim(), role },
      {
        onSuccess: (result) => {
          onCreated(result.user.name, result.password);
          setName('');
          setEmail('');
          setRole('MEMBER');
        },
      },
    );
  };

  return (
    <form onSubmit={handleSubmit} className="rounded-lg border border-border bg-panel p-4">
      <h2 className="text-sm font-medium">Novo usuário</h2>
      <p className="mt-1 text-xs text-muted">A senha é gerada pelo Studio e mostrada uma vez.</p>
      <div className="mt-3 grid grid-cols-1 gap-3 md:grid-cols-[1fr_1fr_12rem_auto] md:items-end">
        <Field label="Nome">
          <TextInput value={name} onChange={(event) => setName(event.target.value)} required />
        </Field>
        <Field label="E-mail">
          <TextInput type="email" value={email} onChange={(event) => setEmail(event.target.value)} required />
        </Field>
        <Field label="Papel">
          <Select value={role} onChange={(event) => setRole(event.target.value as UserRole)}>
            {(Object.keys(roleLabels) as UserRole[]).map((entry) => (
              <option key={entry} value={entry}>
                {roleLabels[entry]}
              </option>
            ))}
          </Select>
        </Field>
        <Button type="submit" variant="primary" disabled={create.isPending || !name.trim() || !email.trim()}>
          {create.isPending ? 'Criando...' : 'Criar usuário'}
        </Button>
      </div>
      <div className="mt-2">
        <ErrorText error={create.error} />
      </div>
    </form>
  );
}
